//! Checks the reference vectors in `vectors.txt`, generated by
//! `gen_vectors.py` from Python's `decimal` / `_pydecimal` modules.
//!
//! Results are compared by their exact `to_scientific_string()` form, so the
//! scale (trailing zeros) must match as well as the value.

use std::collections::BTreeMap;
use std::hash::{DefaultHasher, Hash, Hasher};

use feel_decimal::{Decimal, RoundingMode};

const VECTORS: &str = include_str!("vectors.txt");

fn operand(s: &str) -> Decimal {
    let d = Decimal::parse(s).unwrap_or_else(|| panic!("operand does not parse: {s}"));
    assert_eq!(d.to_scientific_string(), s, "operand round trip");
    d
}

fn show(r: Option<Decimal>) -> String {
    match r {
        Some(d) => d.to_scientific_string(),
        None => "null".to_string(),
    }
}

fn mode(s: &str) -> RoundingMode {
    match s {
        "HalfEven" => RoundingMode::HalfEven,
        "HalfUp" => RoundingMode::HalfUp,
        "HalfDown" => RoundingMode::HalfDown,
        "Up" => RoundingMode::Up,
        "Down" => RoundingMode::Down,
        "Floor" => RoundingMode::Floor,
        "Ceiling" => RoundingMode::Ceiling,
        _ => panic!("unknown rounding mode {s}"),
    }
}

fn hash_of(x: &Decimal) -> u64 {
    let mut h = DefaultHasher::new();
    x.hash(&mut h);
    h.finish()
}

fn eval(t: &[&str]) -> (String, String) {
    let last = t[t.len() - 1].to_string();
    let got = match t[0] {
        "add" => show(operand(t[1]).add(&operand(t[2]))),
        "sub" => show(operand(t[1]).sub(&operand(t[2]))),
        "mul" => show(operand(t[1]).mul(&operand(t[2]))),
        "div" => show(operand(t[1]).div(&operand(t[2]))),
        "rem" => show(operand(t[1]).rem(&operand(t[2]))),
        "modulo" => show(operand(t[1]).modulo(&operand(t[2]))),
        "cmp" => {
            let (a, b) = (operand(t[1]), operand(t[2]));
            let c = a.cmp(&b) as i32;
            assert_eq!(a == b, c == 0);
            if a == b {
                assert_eq!(hash_of(&a), hash_of(&b), "hash consistency {a:?} {b:?}");
            }
            assert_eq!(b.cmp(&a) as i32, -c, "antisymmetry");
            c.to_string()
        }
        "set_scale" => show(operand(t[1]).set_scale(t[2].parse().unwrap(), mode(t[3]))),
        "round_to_scale" => show(operand(t[1]).round_to_scale(t[2].parse().unwrap(), mode(t[3]))),
        "normalize" => show(Some(operand(t[1]).normalize())),
        "floor" => show(Some(operand(t[1]).floor())),
        "ceil" => show(Some(operand(t[1]).ceil())),
        "trunc" => show(Some(operand(t[1]).trunc())),
        "pow_i" => show(operand(t[1]).pow_i64(t[2].parse().unwrap())),
        "pow" => show(operand(t[1]).pow(&operand(t[2]))),
        "sqrt" => show(operand(t[1]).sqrt()),
        "exp" => show(operand(t[1]).exp()),
        "ln" => show(operand(t[1]).ln()),
        "log10" => show(operand(t[1]).log10()),
        "parse" => show(Decimal::parse(t[1])),
        "plain" => operand(t[1]).to_string(),
        op => panic!("unknown op {op}"),
    };
    (got, last)
}

#[test]
fn reference_vectors() {
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    let mut failures = Vec::new();
    for (i, line) in VECTORS.lines().enumerate() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let t: Vec<&str> = line.split(' ').collect();
        *counts.entry(t[0]).or_default() += 1;
        let (got, want) = eval(&t);
        if got != want {
            failures.push(format!("line {}: {line}\n    got {got}", i + 1));
        }
    }
    let total: usize = counts.values().sum();
    eprintln!("checked {total} vectors: {counts:?}");
    assert!(total > 10_000, "too few vectors: {total}");
    if !failures.is_empty() {
        let shown: Vec<_> = failures.iter().take(40).cloned().collect();
        panic!("{} of {total} vectors failed:\n{}", failures.len(), shown.join("\n"));
    }
}
